add_action( 'wp_enqueue_scripts', 'perfectpixel_disable_jquery_migrate', -1 );

function perfectpixel_disable_jquery_migrate() {
	$scripts = wp_scripts();
	if ( isset( $scripts->registered['jquery'] ) ) {
		$scripts->registered['jquery']->deps = array_values( array_diff( $scripts->registered['jquery']->deps, array( 'jquery-migrate' ) ) );
	}
}
